const STOCK_KEY='izdelie-stock-v4',VARIANT_KEY='izdelie-variants-v4',LINK_KEY='izdelie-price-links-v4';let analysisQty=state.qty,priceTarget=null,costSection='material';
function proNav(){return `<div class="navlabel">ПЛАНИРОВАНИЕ</div><button class="${page===12?'active':''}" onclick="go(12)">⇄ Сравнение вариантов</button><button class="${page===13?'active':''}" onclick="go(13)">◎ Целевая цена</button><button class="${page===14?'active':''}" onclick="go(14)">▦ План закупки</button><button class="${page===15?'active':''}" onclick="go(15)">↳ Структура стоимости</button><button class="${page===16?'active':''}" onclick="go(16)">↗ Источники цен</button><button id="cloudNav" onclick="go(17)">☁ Сервер и копии${window.cloudIndicator?' · '+esc(window.cloudIndicator):''}</button>`}
function variants(){const a=readJSON(VARIANT_KEY,[]);return Array.isArray(a)?a.filter(x=>x&&/^[a-zA-Z0-9-]+$/.test(x.id)&&validState(x.calculation)):[]}
function rememberVariant(){modal('Добавить вариант для сравнения',`<div class="field"><label for="variantName">Название варианта</label><input id="variantName" value="${esc(state.name)}"></div><p class="small">Сохранится состав и ставки текущего расчёта. Сравнение использует общий выбранный тираж.</p><button class="primary" onclick="saveVariant()">Добавить вариант</button>`)}
function saveVariant(){const name=$('variantName').value.trim();if(!name||!validState(state)){toast('Укажите название и исправьте параметры расчёта');return}const a=variants();a.push({id:uid(),name,date:stamp(),calculation:cleanCalculation(state)});if(writeJSON(VARIANT_KEY,a)){$('modal').close();go(12)}}
function updateVariant(){const a=variants(),v=a.find(x=>x.id===state.variantId);if(!v||!validState(state)){toast('Откройте вариант для редактирования из сравнения');return}v.calculation=cleanCalculation(state);v.date=stamp();if(writeJSON(VARIANT_KEY,a)){toast('Вариант обновлён');go(12)}}
function editVariant(i){const v=variants()[i];if(!v||!keepCurrent())return;state=cleanCalculation(v.calculation);state.variantId=v.id;persist();go(0);toast('Измените состав и нажмите «Обновить вариант сравнения» в результате')}
function comparePicker(){modal('Добавить из базы изделий',`<p class="small">Добавляется последняя сохранённая версия. После этого она независима от базы.</p><div class="catalog-results">${library().map((e,i)=>`<div class="version-row"><div>${esc(e.name)}<span class="source">${esc(e.code)} · v${e.revisions.length}</span></div><button onclick="variantFromLibrary(${i})">Добавить</button></div>`).join('')||'<p class="small">Сохранённых изделий пока нет.</p>'}</div>`)}
function variantFromLibrary(i){const e=library()[i];if(!e)return;const a=variants();a.push({id:uid(),name:e.name,date:stamp(),calculation:cleanCalculation(e.revisions.at(-1).calculation)});if(writeJSON(VARIANT_KEY,a)){$('modal').close();go(12)}}
function removeVariant(i){const a=variants();a.splice(i,1);if(writeJSON(VARIANT_KEY,a))renderVariants()}
function renderVariants(){const a=variants(),q=Number.isInteger(analysisQty)&&analysisQty>0?analysisQty:1,rs=a.map(v=>CostEngine.calculate(v.calculation,q));$('app').innerHTML=title('Планирование / Комплектации','Сравнение вариантов','Сравните материалы, покрытия и операции при одинаковом размере партии.','Снимки расчётов')+`<div class="toolbar"><button class="primary" onclick="rememberVariant()">＋ Текущий расчёт</button><button onclick="comparePicker()">＋ Из базы изделий</button>${state.variantId?'<button onclick="updateVariant()">Обновить редактируемый вариант</button>':''}<label for="compareQty">Общий тираж</label><input style="width:110px" id="compareQty" type="number" min="1" value="${q}" oninput="if(Number.isInteger(+this.value)&&+this.value>0){analysisQty=+this.value;refreshCompareTable()}"></div><div class="card" id="comparisonTable"></div><div class="note info">Для изменения комплектации откройте вариант в калькуляторе, измените материалы или операции и сохраните его через «Обновить вариант сравнения». Партия при сравнении не меняет исходные расчёты.</div>`;refreshCompareTable()}
function refreshCompareTable(){const a=variants(),rs=a.map(v=>CostEngine.calculate(v.calculation,analysisQty));if(!a.length){$('comparisonTable').innerHTML='<div class="empty"><b>Добавьте базовый вариант</b>Затем создайте копию с другим материалом или покрытием и сравните стоимость.</div>';return}const metrics=[['Статус',r=>r.partial?'Есть пропуски':'Предварительный'],['Материалы / шт.',r=>money(r.M/analysisQty)],['Работы / шт.',r=>money(r.W/analysisQty)],['Себестоимость / шт.',r=>money(r.costUnit)],['Цена / шт. с НДС',r=>money(r.unit)],['Вся партия с НДС',r=>money(r.total)],['Изменение цены к первому',r=>rs[0].unit?dec((r.unit/rs[0].unit-1)*100)+'%':'—']];$('comparisonTable').innerHTML=`<div class="tablewrap"><table><thead><tr><th>Показатель · ${analysisQty} шт.</th>${a.map(v=>`<th>${esc(v.name)}</th>`).join('')}</tr></thead><tbody>${metrics.map(([n,f])=>`<tr><td>${n}</td>${rs.map(r=>`<td class="number">${f(r)}</td>`).join('')}</tr>`).join('')}<tr><td>Действия</td>${a.map((v,i)=>`<td><div class="row-actions"><button onclick="editVariant(${i})">Редактировать</button><button onclick="variantToQuote(${i})">В КП</button><button onclick="removeVariant(${i})">Убрать из сравнения</button></div></td>`).join('')}</tr></tbody></table></div>`}
function variantToQuote(i){const v=variants()[i];if(v){const c=cleanCalculation(v.calculation);c.qty=analysisQty;addQuoteCalculation(c,'variant-'+v.id);go(8)}}
function renderAnalytics(){const q=Number.isInteger(analysisQty)&&analysisQty>0?analysisQty:state.qty;$('app').innerHTML=title('Планирование / Тираж','Интерактивная аналитика партии','Изменяйте тираж и сразу смотрите цену, закупку и распределение подготовки.','Предварительные сценарии')+`<div class="card"><div class="grid2"><div><label for="batchRange">Размер партии</label><input id="batchRange" type="range" min="1" max="500" step="1" value="${Math.min(q,500)}" oninput="analysisQty=+this.value;$('batchNumber').value=this.value;refreshBatch()"></div><div><label for="batchNumber">Количество изделий, шт.</label><input id="batchNumber" type="number" min="1" step="1" value="${q}" oninput="if(Number.isInteger(+this.value)&&+this.value>0){analysisQty=+this.value;$('batchRange').value=Math.min(+this.value,500);refreshBatch()}"></div></div><div class="mini-actions">${[1,5,10,25,50,100].map(n=>`<button onclick="analysisQty=${n};$('batchNumber').value=${n};$('batchRange').value=${n};refreshBatch()">${n} шт.</button>`).join('')}<button class="primary" onclick="set('qty',analysisQty);toast('Размер партии применён к рабочему расчёту')">Применить к заказу</button></div></div><div id="batchMetrics"></div><div class="card"><div class="cardhead"><h2>Цена за изделие по тиражам</h2><button onclick="go(15)">Разобрать стоимость →</button></div><div id="batchChart"></div></div><div class="card"><h2>Сравнение тиражей</h2><div id="batchTable" class="tablewrap"></div></div><div class="note info">Подготовка распределяется на партию, закупка округляется до целых заготовок и упаковок. Оптовые скидки и рост производительности автоматически не предполагаются. Все сценарии используют один состав изделия.</div>`;refreshBatch()}
function refreshBatch(){const r=CostEngine.calculate(state,analysisQty),base=CostEngine.calculate(state,1),fixed=r.rows.reduce((s,l)=>s+(l.operationCost?l.operationCost.setup:(l.scope==='batch'?l.amount||0:0)),0);$('batchMetrics').innerHTML=`<div class="kpis">${[['Цена / шт. с НДС',money(r.unit)],['Себестоимость / шт.',money(r.costUnit)],['Денежная закупка',money(r.cash)],['Разовые затраты / шт.',money(fixed/analysisQty)]].map(([n,v],i)=>`<div class="kpi ${i===0?'featured':''}"><div class="small">${n}</div><div class="big">${v}</div><div class="small">${r.partial?'Известная часть · ':''}${analysisQty} шт.</div></div>`).join('')}</div>`;const qs=[...new Set([1,5,10,25,50,100,analysisQty])].sort((a,b)=>a-b),rs=qs.map(q=>CostEngine.calculate(state,q)),mx=Math.max(...rs.map(x=>x.unit).filter(Number.isFinite),1),points=rs.map((x,i)=>[65+i*640/(rs.length-1),235-(Number.isFinite(x.unit)?x.unit:0)/mx*180]);$('batchChart').innerHTML=`<svg class="chart" viewBox="0 0 770 285" role="img" aria-label="Цена за изделие по тиражам">${[0,.5,1].map(f=>`<line x1="65" x2="730" y1="${235-f*180}" y2="${235-f*180}" stroke="#e1e7d9"/><text x="0" y="${239-f*180}">${dec(mx*f)}</text>`).join('')}<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#315b48" stroke-width="3"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="${qs[i]===analysisQty?7:4}" fill="#315b48"><title>${qs[i]} шт.: ${money(rs[i].unit)}</title></circle><text x="${p[0]}" y="263" text-anchor="middle">${qs[i]} шт.</text>`).join('')}</svg>`;$('batchTable').innerHTML=`<table><thead><tr><th>Тираж</th><th class="number">Закупка</th><th class="number">Цена / шт.</th><th class="number">Изменение к 1 шт.</th><th class="number">Вся партия</th></tr></thead><tbody>${rs.map(x=>`<tr ${x.q===analysisQty?'class="selected-scenario"':''}><td><button onclick="analysisQty=${x.q};$('batchNumber').value=${x.q};$('batchRange').value=Math.min(${x.q},500);refreshBatch()">${x.q} шт.</button></td><td class="number">${money(x.cash)}</td><td class="number">${money(x.unit)}</td><td class="number">${base.unit?dec((x.unit/base.unit-1)*100)+'%':'—'}</td><td class="number">${money(x.total)}</td></tr>`).join('')}</tbody></table>`}
let targetContext='';
function renderTarget(){const key=ReviewCore.signature(state);if(targetContext!==key){analysisQty=state.qty;priceTarget=null;targetContext=key;}const r=CostEngine.calculate(state,analysisQty);if(priceTarget===null)priceTarget=Number.isFinite(r.unit)?Math.round(r.unit*100)/100:0;$('app').innerHTML=title('Переговоры / Цена заказчика','Целевая цена','Проверьте прибыль и маржу на сопоставимой базе без выходного НДС.','Внутренний анализ')+`<div class="card"><div class="grid2"><div><label for="targetQty">Партия, шт.</label><input id="targetQty" type="number" min="1" step="1" value="${analysisQty}" oninput="if(Number.isInteger(+this.value)&&+this.value>0){analysisQty=+this.value;refreshTarget()}"></div><div><label for="targetPrice">Цена заказчика с НДС, ₽ / шт.</label><input id="targetPrice" type="number" min="0" step="0.01" value="${priceTarget}" oninput="priceTarget=this.value===''?null:+this.value;refreshTarget()"></div></div><div class="mini-actions"><button onclick="priceTarget=Math.round(CostEngine.calculate(state,analysisQty).unit*100)/100;$('targetPrice').value=priceTarget;refreshTarget()">По калькуляции</button><button class="primary" onclick="targetToQuote()">Добавить в КП по этой цене</button></div></div><div id="targetMetrics"></div><p class="small">Себестоимость учитывает текущие нормы и ставки. НДС выделяется из цены; прибыль и маржа рассчитываются до НДС. Поступление оплаты, сроки производства и налоги на прибыль здесь не моделируются.</p>`;refreshTarget()}
function refreshTarget(){const t=ProCore.target(state,analysisQty,priceTarget,CostEngine.calculate);if(t.valid&&t.profitIncomplete){$('targetMetrics').innerHTML=`<div class="note"><b>Прибыль и порог безубыточности неизвестны</b><p>В заказе есть услуги с готовой ценой заказчику без внутренних затрат. Заполните их затраты для анализа прибыли.</p><p>Предложение на ${analysisQty} шт. с НДС: ${money(t.total)}.</p></div>`;return;}$('targetMetrics').innerHTML=t.valid?`<div class="kpis">${[['Прибыль / шт. до НДС',money(t.profit)],['Маржа до НДС',t.margin===null?'—':dec(t.margin)+'%'],['Наценка к себестоимости',t.markup===null?'—':dec(t.markup)+'%'],['Порог безубыточности с НДС',money(t.breakEven)]].map(([n,v])=>`<div class="kpi"><div class="small">${n}</div><div class="big">${v}</div></div>`).join('')}</div><div class="note ${t.profit<0?'':'info'}">${t.profit<0?'Цена ниже расчётной себестоимости с НДС. Убыток на партию до НДС: '+money(-t.profit*analysisQty):'Расчётная прибыль партии до НДС: '+money(t.profit*analysisQty)}. Сумма предложения с НДС: ${money(t.total)}.</div>`:'<div class="note">Нужна неотрицательная целевая цена и полный расчёт себестоимости. Исправьте пропуски перед анализом прибыли.</div>'}
function targetToQuote(){const t=ProCore.target(state,analysisQty,priceTarget,CostEngine.calculate);if(!t.valid){toast('Сначала заполните расчёт и целевую цену');return}const c=cleanCalculation(state);c.qty=analysisQty;const key='target-'+uid();addQuoteCalculation(c,key);let l=quoteDraft.items.find(x=>x.key===key);if(!l){toast('Такое изделие уже есть в КП. Измените его цену в конструкторе.');go(8);return}l.override=priceTarget;saveDraft();go(8)}
function inventory(){const a=readJSON(STOCK_KEY,{});return a&&typeof a==='object'&&!Array.isArray(a)?a:{}}
function stockValue(index,value){const p=ProCore.plan(state,inventory(),CostEngine.calculate),row=p.rows[index];if(!row)return;const n=value===''?0:+value;if(!Number.isFinite(n)||n<0){toast('Остаток должен быть неотрицательным');return}const a=inventory();a[row.key]=n;if(writeJSON(STOCK_KEY,a))refreshStockPlan()}
function renderStockPlan(){$('app').innerHTML=title('Производство / Снабжение','План закупки','Укажите доступные остатки и проверьте денежную потребность на текущую партию.','Планирование')+`<div class="card"><div class="cardhead"><h2>${esc(state.name)} · ${state.qty} шт.</h2><button onclick="exportStockPlan()">↓ План CSV</button></div><div class="tablewrap"><table><thead><tr><th>Материал</th><th class="number">Нужно с запасом</th><th>Учтённый остаток</th><th class="number">Использовать</th><th class="number">Закупить</th><th class="number">Остаток закупки</th><th class="number">К оплате</th></tr></thead><tbody id="stockPlanRows"></tbody></table></div></div><div id="stockPlanTotal"></div><div class="note info">Одинаковая номенклатура в одной единице объединяется перед закупкой. Остаток применяется один раз. Стоимость потребляемого складского материала остаётся в себестоимости изделия; здесь рассчитывается денежная закупка. План не резервирует и не списывает склад автоматически.</div>`;const p=ProCore.plan(state,inventory(),CostEngine.calculate);$('stockPlanRows').innerHTML=p.rows.map((l,i)=>`<tr><td class="rowname">${esc(l.name)}<span class="source">${esc(MaterialCore.unitLabel(l.unit))} · кратность ${dec(l.pack)}</span></td><td class="number">${dec(l.need)}</td><td><input aria-label="Остаток: ${esc(l.name)}" style="width:100px" type="number" min="0" step="any" value="${l.stock}" oninput="stockValue(${i},this.value)"></td><td class="number" id="stockUsed-${i}"></td><td class="number" id="stockBuy-${i}"></td><td class="number" id="stockSurplus-${i}"></td><td class="number" id="stockCash-${i}"></td></tr>`).join('')||'<tr><td colspan="7">Добавьте материалы в расчёт.</td></tr>';refreshStockPlan()}
function refreshStockPlan(){const p=ProCore.plan(state,inventory(),CostEngine.calculate);p.rows.forEach((l,i)=>{for(const [field,k] of [['Used','used'],['Buy','buy'],['Surplus','surplus'],['Cash','cash']])if($('stock'+field+'-'+i))$('stock'+field+'-'+i).textContent=k==='cash'?money(l[k]):dec(l[k])});$('stockPlanTotal').innerHTML=`<div class="kpis"><div class="kpi featured"><div class="small">${p.partial?'Известная часть закупки':'Денежная закупка'}</div><div class="big">${money(p.cash)}</div></div><div class="kpi"><div class="small">Материальных позиций</div><div class="big">${p.rows.length}</div></div></div><p class="small">Калькуляционная закупка по отдельным строкам: ${money(p.calculationCash)}. План объединяет одинаковые материалы и учитывает склад: ${money(p.cash)}${p.partial?' (известная часть)':''}. План не меняет себестоимость и сохранённую цену заказа.</p>${p.issues.map(x=>`<div class="issue">${esc(x)}</div>`).join('')}`}
function exportStockPlan(){const p=ProCore.plan(state,inventory(),CostEngine.calculate),cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'").replaceAll('"','""')+'"',rows=[['Материал','Единица','Потребность с запасом','Остаток','Использовать','Закупить','Излишек закупки','Денежная закупка'],...p.rows.map(l=>[l.name,l.unit,l.need,l.stock,l.used,l.buy,l.surplus,l.cash])];download('plan-zakupki.csv','\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8')}
function interactiveIssuesHTML(){const a=ProCore.issues(state);return a.length?a.map(x=>`<div class="issue"><div>${esc(x.message)}</div><button class="iconbtn" onclick="jumpToIssue(${x.index},'${x.field}')">${x.field==='source'?'Выбрать источник':'Исправить'} →</button></div>`).join(''):'<p class="small">Замечаний по заполнению нет. Проверьте комплектность изделия.</p>'}
function jumpToIssue(index,field){if(index<0){go(field==='qty'?0:field==='lines'?1:3);requestAnimationFrame(()=>$('f-'+field)?.focus());return}const l=state.lines[index];if(!l)return;if(field==='source'){sourcePicker(index);return}go(l.kind==='work'?2:1);editLine(l.id);requestAnimationFrame(()=>$('l-'+field)?.focus())}
function renderBreakdown(){const r=CostEngine.calculate(state);$('app').innerHTML=title('Аналитика / Статьи затрат','Структура себестоимости','Нажмите на статью, чтобы увидеть её состав и перейти к редактированию.','Партия '+state.qty+' шт.')+`<div class="kpis">${[['material','Материалы',r.M],['work','Работы',r.W],['overhead','Накладные',r.overhead],['transport','Транспорт',r.transport]].map(([k,n,v])=>`<button class="kpi ${costSection===k?'featured':''}" onclick="costSection='${k}';renderBreakdown()"><div class="small">${n}</div><div class="big">${money(v)}</div><div class="small">${r.C?dec(v/r.C*100):0}% себестоимости</div></button>`).join('')}</div><div class="card" id="costRows"></div><p class="small">${r.partial?'Есть пропуски: показана известная часть затрат.':'Расчёт предварительный.'} Общая себестоимость партии: ${money(r.C)}. Наценка и НДС в эту диаграмму не входят.</p>`;const chosen=r.rows.map((l,i)=>({...l,index:i})).filter(l=>costSection==='work'||costSection==='overhead'?l.kind==='work':l.kind==='material'&&(costSection!=='transport'||!l.deliveryIncluded));const factor=costSection==='overhead'?state.overhead/100:costSection==='transport'?state.transport/100:1;$('costRows').innerHTML=`<h2>${{material:'Материалы',work:'Работы',overhead:'Накладные — '+state.overhead+'% от работ',transport:'Транспорт — '+state.transport+'% от материалов без включённой доставки'}[costSection]}</h2><div class="tablewrap"><table><thead><tr><th>Позиция</th><th>Группа</th><th class="number">База на партию</th><th class="number">В статье</th><th></th></tr></thead><tbody>${chosen.map(l=>`<tr><td class="rowname">${esc(l.name)}</td><td>${esc(l.group)}</td><td class="number">${money(l.amount)}</td><td class="number">${money(l.amount===null?null:l.amount*factor)}</td><td><button onclick="jumpToIssue(${l.index},'price')">Открыть</button></td></tr>`).join('')}</tbody></table></div>`}
function priceLinks(){const a=readJSON(LINK_KEY,{});return a&&typeof a==='object'&&!Array.isArray(a)?a:{}}
function applyPreferredSources(){const links=priceLinks();for(const c of CATALOG){const l=links[c.id+'|'+c.unit],p=l&&PURCHASE_DATA.records.find(p=>p.id===l.purchaseId);if(!p?.eligible||!Number.isFinite(l.factor)||l.factor<=0||l.confirmed!==true)continue;c.previousPrice??=c.price;c.price=p.price*l.factor;c.date=p.date;c.purchaseId=p.id;c.purchaseSource=PurchaseCore.sourceText(p)+' · '+l.factor+' ед. источника / '+c.unit+' · '+l.reason;c.updateReason=l.reason;c.priceFactor=l.factor;}}
applyPreferredSources();
let sourceLineIndex=null,sourcePurchaseId=null;
function sourcePicker(index){const l=state.lines[index];if(!l)return;sourceLineIndex=index;modal('Выбрать закупочную цену',`<h3>${esc(l.name)} · ставка за ${esc(MaterialCore.unitLabel(l.unit))}</h3><p class="small">Выберите ту же номенклатуру, затем проверьте характеристики и пересчёт единиц. Данные с замечаниями источника исключены.</p><div class="toolbar"><input id="sourceSearch" placeholder="Поиск по закупочной номенклатуре" oninput="sourcePickerRows()"></div><div class="catalog-results" id="sourceResults"></div>`);sourcePickerRows()}
function sourcePickerRows(){const l=state.lines[sourceLineIndex],q=$('sourceSearch').value.toLowerCase(),a=PURCHASE_DATA.records.filter(p=>p.eligible&&p.kind===l.kind&&q.split(/\s+/).every(w=>p.name.toLowerCase().includes(w)));$('sourceResults').innerHTML=`<p class="small">Найдено ${a.length}; показано до 70.</p><table><thead><tr><th>Номенклатура</th><th>Единица</th><th class="number">Последняя цена</th><th>Дата</th><th></th></tr></thead><tbody>${a.slice(0,70).map(p=>`<tr><td>${esc(p.name)}</td><td>${esc(MaterialCore.unitLabel(p.unit))}</td><td class="number">${money(p.price)}</td><td>${p.date}</td><td><button onclick="sourceConversion('${p.id}')">Выбрать</button></td></tr>`).join('')}</tbody></table>`}
function sourceConversion(id){const l=state.lines[sourceLineIndex],p=PURCHASE_DATA.records.find(x=>x.id===id);if(!l||!p?.eligible)return;sourcePurchaseId=id;const c=CATALOG.find(c=>c.id===l.catalogId),f=ProCore.unitFactor(l.unit,p.unit,c);modal('Проверка номенклатуры и единиц',`<h3>${esc(l.name)}</h3><p class="small">Источник: ${esc(p.name)} · ${money(p.price)} / ${esc(MaterialCore.unitLabel(p.unit))} · ${p.date}</p><div class="field"><label for="sourceFactor">Единиц источника (${esc(MaterialCore.unitLabel(p.unit))}) на одну единицу позиции (${esc(MaterialCore.unitLabel(l.unit))})</label><input id="sourceFactor" type="number" min="0.000000001" step="any" value="${f.factor??''}" oninput="sourcePreview()"><span class="hint">${esc(f.reason)}</span></div><div class="field"><label for="sourceReason">Основание сопоставления / характеристики</label><textarea id="sourceReason" rows="3" placeholder="Марка, размеры, сорт, покрытие, фасовка и формула пересчёта">${esc(f.reason)}</textarea></div><div class="note info" id="sourcePreview"></div><label class="checkrow"><input id="sourceConfirm" type="checkbox">Проверены номенклатура, характеристики и единицы; это подходящая цена для данной позиции</label><label class="checkrow"><input id="sourceRemember" type="checkbox" ${l.catalogId?'checked':''}>Запомнить как предпочтительный источник для новых расчётов этой позиции</label><div class="mini-actions"><button class="primary" onclick="commitSource()">Применить источник</button><button onclick="sourcePicker(${sourceLineIndex})">Назад к выбору</button></div><p class="small">Закупка историческая. Фасовку, доступность и доставку необходимо проверить отдельно; НДС, включённый в исходную цену, повторно не начисляется.</p>`);sourcePreview()}
function sourcePreview(){const p=PURCHASE_DATA.records.find(x=>x.id===sourcePurchaseId),f=+$('sourceFactor').value,l=state.lines[sourceLineIndex];$('sourcePreview').textContent=f>0&&Number.isFinite(f)?'Цена в калькуляции: '+money(p.price*f)+' / '+l.unit:'Укажите положительный коэффициент пересчёта'}
function commitSource(){const l=state.lines[sourceLineIndex],p=PURCHASE_DATA.records.find(x=>x.id===sourcePurchaseId),factor=+$('sourceFactor').value,reason=$('sourceReason').value.trim();if(!l||!p?.eligible||!Number.isFinite(factor)||factor<=0||!Number.isFinite(p.price*factor)||!reason||!$('sourceConfirm').checked){toast('Нужны коэффициент, основание и подтверждение характеристик');return}l.price=p.price*factor;l.date=p.date;l.source=PurchaseCore.sourceText(p)+' · '+factor+' ед. источника / '+l.unit+' · '+reason;l.confirmed=false;if($('sourceRemember').checked&&l.catalogId){const a=priceLinks();a[l.catalogId+'|'+l.unit]={purchaseId:p.id,factor,reason,confirmed:true,date:stamp()};writeJSON(LINK_KEY,a);applyPreferredSources()}persist();$('modal').close();render();toast('Источник и пересчёт цены сохранены')}
function renderPriceSources(){const a=Object.entries(priceLinks());$('app').innerHTML=title('Справочники / Сопоставления','Предпочтительные источники цен','Свяжите материал с закупочной записью и сохраните объяснение пересчёта.','Для новых добавлений')+`<div class="card"><h2>Позиции текущего расчёта</h2><div class="tablewrap"><table><thead><tr><th>Позиция</th><th>Единица</th><th class="number">Цена</th><th>Источник</th><th></th></tr></thead><tbody>${state.lines.map((l,i)=>`<tr><td>${esc(l.name)}</td><td>${esc(MaterialCore.unitLabel(l.unit))}</td><td class="number">${money(l.price)}</td><td class="small">${esc(l.source)}</td><td><button onclick="sourcePicker(${i})">Выбрать источник</button></td></tr>`).join('')}</tbody></table></div></div><div class="card"><h2>Сохранённые соответствия · ${a.length}</h2>${a.map(([key,x])=>{const p=PURCHASE_DATA.records.find(p=>p.id===x.purchaseId),c=CATALOG.find(c=>key===c.id+'|'+c.unit);return `<div class="version-row"><div><b>${esc(c?.name||key)}</b><span class="source">${esc(p?.name||x.purchaseId)} · коэффициент ${x.factor} · ${esc(x.reason)}</span></div></div>`}).join('')||'<p class="small">Выберите источник у позиции расчёта и отметьте «Запомнить».</p>'}</div><div class="note info">Сохранённые версии изделий и выданные КП сохраняют свои ставки. Предпочтительный источник используется при новых добавлениях позиции из справочника.</div>`}

render();
